/**
 * Bank Account Input Component — Models, Types, and Validators
 */
// ── Constants ───────────────────────────────────────────────────────────────────
export const BANK_ACCOUNT_MODE_CONFIGS = {
    indian: {
        minLength: 9,
        maxLength: 18,
        allowAlpha: false,
        groupSize: 4,
    },
    iban: {
        minLength: 15,
        maxLength: 34,
        allowAlpha: true,
        groupSize: 4,
    },
    generic: {
        minLength: 5,
        maxLength: 34,
        allowAlpha: true,
        groupSize: 4,
    },
};
// ── IBAN Country Lengths ────────────────────────────────────────────────────────
const IBAN_LENGTHS = {
    AL: 28, AD: 24, AT: 20, AZ: 28, BH: 22, BY: 28, BE: 16, BA: 20,
    BR: 29, BG: 22, CR: 22, HR: 21, CY: 28, CZ: 24, DK: 18, DO: 28,
    TL: 23, EE: 20, FO: 18, FI: 18, FR: 27, GE: 22, DE: 22, GI: 23,
    GR: 27, GL: 18, GT: 28, HU: 28, IS: 26, IQ: 23, IE: 22, IL: 23,
    IT: 27, JO: 30, KZ: 20, XK: 20, KW: 30, LV: 21, LB: 28, LI: 21,
    LT: 20, LU: 20, MK: 19, MT: 31, MR: 27, MU: 30, MC: 27, MD: 24,
    ME: 22, NL: 18, NO: 15, PK: 24, PS: 29, PL: 28, PT: 25, QA: 29,
    RO: 24, SM: 27, SA: 24, RS: 22, SK: 24, SI: 19, ES: 24, SE: 24,
    CH: 21, TN: 24, TR: 26, UA: 29, AE: 23, GB: 22, VG: 24,
};
// ── Validators (Pure Functions) ─────────────────────────────────────────────────
/**
 * Validate an Indian bank account number.
 * Rules: numeric only, 9-18 digits.
 */
export function validateIndianAccount(value) {
    const errors = [];
    const cleaned = value.replace(/\s/g, '');
    if (!cleaned) {
        return ['Account number is required'];
    }
    if (!/^\d+$/.test(cleaned)) {
        errors.push('Account number must contain only digits');
    }
    if (cleaned.length < 9) {
        errors.push('Account number must be at least 9 digits');
    }
    if (cleaned.length > 18) {
        errors.push('Account number cannot exceed 18 digits');
    }
    return errors;
}
/**
 * Validate an IBAN using MOD-97 checksum algorithm.
 * Structure: 2-letter country code + 2 check digits + BBAN (up to 30 chars)
 */
export function validateIBAN(value) {
    const errors = [];
    const cleaned = value.replace(/\s/g, '').toUpperCase();
    if (!cleaned) {
        return ['IBAN is required'];
    }
    // Basic structure check
    if (!/^[A-Z]{2}\d{2}[A-Z0-9]+$/.test(cleaned)) {
        errors.push('IBAN must start with a 2-letter country code followed by 2 check digits');
        return errors;
    }
    // Country code validation
    const countryCode = cleaned.substring(0, 2);
    const expectedLength = IBAN_LENGTHS[countryCode];
    if (!expectedLength) {
        errors.push(`Unknown IBAN country code: ${countryCode}`);
        return errors;
    }
    if (cleaned.length !== expectedLength) {
        errors.push(`IBAN for ${countryCode} must be exactly ${expectedLength} characters (got ${cleaned.length})`);
        return errors;
    }
    // MOD-97 checksum validation
    if (!verifyIBANChecksum(cleaned)) {
        errors.push('IBAN checksum is invalid');
    }
    return errors;
}
/**
 * Validate a generic bank account number.
 */
export function validateGenericAccount(value, config) {
    const errors = [];
    const cleaned = value.replace(/\s/g, '');
    if (!cleaned) {
        return ['Account number is required'];
    }
    const pattern = config.allowAlpha ? /^[A-Za-z0-9]+$/ : /^\d+$/;
    if (!pattern.test(cleaned)) {
        errors.push(config.allowAlpha
            ? 'Account number must contain only letters and digits'
            : 'Account number must contain only digits');
    }
    if (config.minLength && cleaned.length < config.minLength) {
        errors.push(`Account number must be at least ${config.minLength} characters`);
    }
    if (config.maxLength && cleaned.length > config.maxLength) {
        errors.push(`Account number cannot exceed ${config.maxLength} characters`);
    }
    return errors;
}
/**
 * MOD-97 checksum verification for IBAN.
 * Rearranges the IBAN, converts letters to numbers, and checks mod 97 === 1.
 */
function verifyIBANChecksum(iban) {
    // Move first 4 chars to end
    const rearranged = iban.substring(4) + iban.substring(0, 4);
    // Convert letters to numbers (A=10, B=11, ..., Z=35)
    let numericString = '';
    for (const char of rearranged) {
        const code = char.charCodeAt(0);
        if (code >= 65 && code <= 90) {
            numericString += (code - 55).toString();
        }
        else {
            numericString += char;
        }
    }
    // Compute mod 97 using chunked approach (handles large numbers)
    let remainder = 0;
    for (let i = 0; i < numericString.length; i += 7) {
        const chunk = remainder.toString() + numericString.substring(i, i + 7);
        remainder = parseInt(chunk, 10) % 97;
    }
    return remainder === 1;
}
/**
 * Format account number with spaces for display readability.
 */
export function formatAccountDisplay(value, groupSize) {
    const cleaned = value.replace(/\s/g, '');
    if (!cleaned || groupSize <= 0)
        return cleaned;
    const groups = [];
    for (let i = 0; i < cleaned.length; i += groupSize) {
        groups.push(cleaned.substring(i, i + groupSize));
    }
    return groups.join(' ');
}
/**
 * Mask account number for privacy display.
 * Shows only the last `visibleCount` characters, rest as bullets.
 */
export function maskAccountNumber(value, visibleCount = 4) {
    const cleaned = value.replace(/\s/g, '');
    if (cleaned.length <= visibleCount)
        return cleaned;
    const masked = '•'.repeat(cleaned.length - visibleCount);
    const visible = cleaned.slice(-visibleCount);
    return masked + visible;
}
