import { inject, InjectionToken } from '@angular/core';
import { Router, } from '@angular/router';
import { AuthService } from './auth.service';
export const AUTH_FALLBACK_URL = new InjectionToken('AUTH_FALLBACK_URL', {
    factory: () => 'login',
});
export const AUTH_DASHBOARD_URL = new InjectionToken('AUTH_DASHBOARD_URL', {
    factory: () => '/dashboard',
});
export const canActivateAuthGuard = (next, state) => {
    const authService = inject(AuthService);
    const router = inject(Router);
    const authenticated = authService.isAuthenticated();
    if (authenticated) {
        console.log('authenticated');
        return true;
    }
    else {
        console.log('Could not authenticate');
        const appDefaultFallback = inject(AUTH_FALLBACK_URL);
        const targetUrl = next.data?.['fallbackUrl'] || appDefaultFallback;
        return router.createUrlTree([targetUrl], {
            queryParams: { redirectURL: state.url },
        });
    }
};
export const canMatchAuthGuard = (route) => {
    const authService = inject(AuthService);
    const router = inject(Router);
    const authenticated = authService.isAuthenticated();
    if (authenticated) {
        console.log('authenticated');
        return true;
    }
    else {
        console.log('Could not authenticate');
        const appDefaultFallback = inject(AUTH_FALLBACK_URL);
        const targetUrl = route.data?.['fallbackUrl'] || appDefaultFallback;
        const attemptUrl = router.currentNavigation()?.extractedUrl.toString() || '/dashboard';
        return router.createUrlTree([targetUrl], {
            queryParams: { redirectURL: attemptUrl },
        });
    }
};
export const canDeActivateAuthGuard = (component) => {
    return component.canDeactivate() ?? true;
};
export const canActivateGuestGuard = (next, state) => {
    const authService = inject(AuthService);
    const router = inject(Router);
    const appDefaultDashboard = inject(AUTH_DASHBOARD_URL);
    if (authService.isAuthenticated()) {
        const targetUrl = next.data?.['dashboardUrl'] || appDefaultDashboard;
        return router.createUrlTree([targetUrl], {
            queryParams: { redirectURL: state.url },
        });
    }
    return true;
};
