/**
 * Date Picker Helper Functions
 *
 * Pure utility functions for calendar generation, date validation, and range logic.
 * No Angular DI or side effects — all functions are stateless.
 */
// ============================================================================
// DATE UTILITIES
// ============================================================================
/**
 * Returns the midnight timestamp for a given date (strips time portion).
 */
export function getMidnightTime(d) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}
/**
 * Checks if two dates represent the same calendar day.
 */
export function isSameDay(date1, date2) {
    return (date1.getDate() === date2.getDate() &&
        date1.getMonth() === date2.getMonth() &&
        date1.getFullYear() === date2.getFullYear());
}
// ============================================================================
// DATE VALIDATION
// ============================================================================
/**
 * Determines if a date is disabled based on configuration constraints.
 */
export function isDateDisabled(date, config) {
    const { minDate, maxDate, disabledDates } = config;
    const normalizedDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    if (minDate) {
        const normalizedMin = new Date(minDate.getFullYear(), minDate.getMonth(), minDate.getDate());
        if (normalizedDate < normalizedMin)
            return true;
    }
    if (maxDate) {
        const normalizedMax = new Date(maxDate.getFullYear(), maxDate.getMonth(), maxDate.getDate());
        if (normalizedDate > normalizedMax)
            return true;
    }
    if (disabledDates && disabledDates.some((d) => isSameDay(d, date))) {
        return true;
    }
    return false;
}
/**
 * Determines if a timestamp falls within a range (inclusive).
 * Handles both completed ranges and hover-based tentative ranges.
 */
export function isDateTimeInRange(dateTime, startLimit, endLimit, hoverLimit) {
    if (startLimit === null)
        return false;
    if (endLimit !== null) {
        return dateTime >= startLimit && dateTime <= endLimit;
    }
    if (hoverLimit !== null) {
        if (hoverLimit >= startLimit) {
            return dateTime >= startLimit && dateTime <= hoverLimit;
        }
        else {
            return dateTime >= hoverLimit && dateTime <= startLimit;
        }
    }
    return false;
}
/**
 * Generates the full 6×7 calendar grid for single-selection mode.
 */
export function generateSingleModeCalendar(params) {
    const { currentMonth, firstDayOfWeek, today, selectedDate, config } = params;
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const days = generateDateGrid(year, month, firstDayOfWeek);
    const todayTime = getMidnightTime(today);
    const selectedTime = selectedDate ? getMidnightTime(selectedDate) : null;
    return days.map(({ date, isCurrentMonth }) => {
        const dateTime = getMidnightTime(date);
        return {
            date,
            day: date.getDate(),
            month: date.getMonth(),
            year: date.getFullYear(),
            isCurrentMonth,
            isToday: dateTime === todayTime,
            isSelected: selectedTime !== null && dateTime === selectedTime,
            isRangeStart: false,
            isRangeEnd: false,
            isInRange: false,
            isDisabled: isDateDisabled(date, config),
        };
    });
}
/**
 * Generates the full 6×7 calendar grid for range-selection mode.
 */
export function generateRangeModeCalendar(params) {
    const { currentMonth, firstDayOfWeek, today, rangeValue, hoveredDate, config } = params;
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const days = generateDateGrid(year, month, firstDayOfWeek);
    const todayTime = getMidnightTime(today);
    const startLimit = rangeValue?.start ? getMidnightTime(rangeValue.start) : null;
    const endLimit = rangeValue?.end ? getMidnightTime(rangeValue.end) : null;
    const hoverLimit = hoveredDate ? getMidnightTime(hoveredDate) : null;
    return days.map(({ date, isCurrentMonth }) => {
        const dateTime = getMidnightTime(date);
        const isRangeStart = startLimit !== null && dateTime === startLimit;
        const isRangeEnd = endLimit !== null && dateTime === endLimit;
        const isInRange = isDateTimeInRange(dateTime, startLimit, endLimit, hoverLimit);
        return {
            date,
            day: date.getDate(),
            month: date.getMonth(),
            year: date.getFullYear(),
            isCurrentMonth,
            isToday: dateTime === todayTime,
            isSelected: isRangeStart || isRangeEnd,
            isRangeStart,
            isRangeEnd,
            isInRange,
            isDisabled: isDateDisabled(date, config),
        };
    });
}
// ============================================================================
// INPUT PARSING
// ============================================================================
/**
 * Splits a range input string into two date parts.
 * Supports " - " and " to " delimiters.
 */
export function splitRangeValue(value) {
    if (value.includes(' - ')) {
        return value.split(' - ').map((p) => p.trim());
    }
    else if (value.includes(' to ')) {
        return value.split(' to ').map((p) => p.trim());
    }
    return [];
}
/**
 * Generates the raw date grid (6 rows × 7 columns = 42 cells) for a given month.
 */
function generateDateGrid(year, month, firstDayOfWeek) {
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    let startDay = firstDay.getDay() - firstDayOfWeek;
    if (startDay < 0)
        startDay += 7;
    const days = [];
    // Previous month days
    const prevMonthLastDay = new Date(year, month, 0).getDate();
    for (let i = startDay - 1; i >= 0; i--) {
        const day = prevMonthLastDay - i;
        days.push({ date: new Date(year, month - 1, day), isCurrentMonth: false });
    }
    // Current month days
    for (let day = 1; day <= lastDay.getDate(); day++) {
        days.push({ date: new Date(year, month, day), isCurrentMonth: true });
    }
    // Next month days (fill to 42 cells)
    const remainingDays = 42 - days.length;
    for (let day = 1; day <= remainingDays; day++) {
        days.push({ date: new Date(year, month + 1, day), isCurrentMonth: false });
    }
    return days;
}
