/**
 * Pure Text Search Utilities
 * Framework-agnostic, reusable text matching and extraction functions
 */
// ============================================================================
// Text Matching Functions
// ============================================================================
/**
 * Check if text contains query
 * @param text - The text to search in
 * @param query - The query to search for
 * @param caseSensitive - Whether the search should be case-sensitive (default: false)
 * @returns True if text contains query
 *
 * @example
 * containsQuery('Hello World', 'world') // true
 * containsQuery('Hello World', 'world', true) // false
 */
export function containsQuery(text, query, caseSensitive = false) {
    if (!text || !query)
        return false;
    const textToSearch = caseSensitive ? text : text.toLowerCase();
    const queryToSearch = caseSensitive ? query : query.toLowerCase();
    return textToSearch.includes(queryToSearch);
}
/**
 * Check if text exactly matches query
 * @param text - The text to compare
 * @param query - The query to match
 * @param caseSensitive - Whether the comparison should be case-sensitive (default: false)
 * @returns True if text exactly matches query
 *
 * @example
 * exactMatch('Hello', 'hello') // true
 * exactMatch('Hello', 'hello', true) // false
 */
export function exactMatch(text, query, caseSensitive = false) {
    if (!text || !query)
        return false;
    const textToCompare = caseSensitive ? text : text.toLowerCase();
    const queryToCompare = caseSensitive ? query : query.toLowerCase();
    return textToCompare === queryToCompare;
}
/**
 * Extract preview text around the search query
 * @param text - The full text to extract from
 * @param query - The query to center the preview around
 * @param contextLength - Number of characters to show around the query (default: 60)
 * @param caseSensitive - Whether the search should be case-sensitive (default: false)
 * @returns Preview text with ellipsis if truncated
 *
 * @example
 * extractPreview('This is a long text with important content', 'important', 20)
 * // Returns: '...text with important conte...'
 */
export function extractPreview(text, query, contextLength = 60, caseSensitive = false) {
    if (!text)
        return '';
    const lowerText = caseSensitive ? text : text.toLowerCase();
    const lowerQuery = caseSensitive ? query : query.toLowerCase();
    const index = lowerText.indexOf(lowerQuery);
    if (index === -1) {
        return text.substring(0, contextLength) + '...';
    }
    const start = Math.max(0, index - contextLength / 2);
    const end = Math.min(text.length, index + query.length + contextLength / 2);
    let preview = text.substring(start, end);
    if (start > 0) {
        preview = '...' + preview;
    }
    if (end < text.length) {
        preview = preview + '...';
    }
    return preview;
}
/**
 * Highlight query in text by wrapping it with markers
 * @param text - The text to highlight in
 * @param query - The query to highlight
 * @param startMarker - The opening marker (default: '<mark>')
 * @param endMarker - The closing marker (default: '</mark>')
 * @param caseSensitive - Whether the search should be case-sensitive (default: false)
 * @returns Text with query wrapped in markers
 *
 * @example
 * highlightQuery('Hello World', 'world', '<b>', '</b>')
 * // Returns: 'Hello <b>World</b>'
 */
export function highlightQuery(text, query, startMarker = '<mark>', endMarker = '</mark>', caseSensitive = false) {
    if (!text || !query)
        return text;
    const flags = caseSensitive ? 'g' : 'gi';
    const escapedQuery = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(${escapedQuery})`, flags);
    return text.replace(regex, `${startMarker}$1${endMarker}`);
}
/**
 * Count occurrences of query in text
 * @param text - The text to search in
 * @param query - The query to count
 * @param caseSensitive - Whether the search should be case-sensitive (default: false)
 * @returns Number of occurrences
 *
 * @example
 * countOccurrences('Hello hello HELLO', 'hello') // 3
 * countOccurrences('Hello hello HELLO', 'hello', true) // 1
 */
export function countOccurrences(text, query, caseSensitive = false) {
    if (!text || !query)
        return 0;
    const textToSearch = caseSensitive ? text : text.toLowerCase();
    const queryToSearch = caseSensitive ? query : query.toLowerCase();
    let count = 0;
    let position = 0;
    while ((position = textToSearch.indexOf(queryToSearch, position)) !== -1) {
        count++;
        position += queryToSearch.length;
    }
    return count;
}
/**
 * Find all positions where query appears in text
 * @param text - The text to search in
 * @param query - The query to find
 * @param caseSensitive - Whether the search should be case-sensitive (default: false)
 * @returns Array of start positions
 *
 * @example
 * findAllPositions('Hello hello HELLO', 'hello')
 * // Returns: [0, 6, 12]
 */
export function findAllPositions(text, query, caseSensitive = false) {
    if (!text || !query)
        return [];
    const positions = [];
    const textToSearch = caseSensitive ? text : text.toLowerCase();
    const queryToSearch = caseSensitive ? query : query.toLowerCase();
    let position = 0;
    while ((position = textToSearch.indexOf(queryToSearch, position)) !== -1) {
        positions.push(position);
        position += queryToSearch.length;
    }
    return positions;
}
