/**
 * Generic comparator for primitive values (string, number, null/undefined)
 * @param a - First value to compare
 * @param b - Second value to compare
 * @returns Negative, zero, or positive for use in Array.sort()
 */
export function defaultCompare(a, b) {
    if (a == null && b == null)
        return 0;
    if (a == null)
        return -1;
    if (b == null)
        return 1;
    if (typeof a === 'string' && typeof b === 'string')
        return a.localeCompare(b);
    return a < b ? -1 : a > b ? 1 : 0;
}
/**
 * Sorts an array of objects by a specified property
 * @param obj - Array of objects to sort
 * @param param - Property name to sort by
 * @returns Sorted array
 */
export const sort = (obj, param) => {
    return obj.sort((a, b) => a[param].toLowerCase() > b[param].toLowerCase() ? 1 : -1);
};
/**
 * Filters an object to include only specified keys
 * @param raw - Object to filter
 * @param allowed - Array of keys to include
 * @returns Filtered object
 */
export const filterByKEY = (raw, allowed) => {
    return Object.keys(raw)
        .filter((key) => allowed.includes(key))
        .reduce((obj, key) => {
        obj[key] = raw[key];
        return obj;
    }, {});
};
/**
 * Filters an object to exclude specified keys
 * @param raw - Object to filter
 * @param allowed - Array of keys to exclude
 * @returns Filtered object
 */
export const omitByKEY = (raw, allowed) => {
    return Object.keys(raw)
        .filter((key) => !allowed.includes(key))
        .reduce((obj, key) => {
        obj[key] = raw[key];
        return obj;
    }, {});
};
/**
 * Checks if all items in arr2 are contained in arr1
 * @param arr1 - First array
 * @param arr2 - Second array
 * @returns True if all items in arr2 are in arr1
 */
export const containsAll = (arr1, arr2) => {
    if (Array.isArray(arr1) && Array.isArray(arr2)) {
        return arr2.every((arr2Item) => arr1.includes(arr2Item));
    }
    return false;
};
/**
 * Checks if any item in arr2 is contained in arr1
 * @param arr1 - First array
 * @param arr2 - Second array
 * @returns True if any item in arr2 is in arr1
 */
export const containsAny = (arr1, arr2) => {
    if (Array.isArray(arr1) && Array.isArray(arr2)) {
        return arr2.some((arr2Item) => arr1.includes(arr2Item));
    }
    return false;
};
/**
 * Replaces null values in an array of objects with a specified value
 * @param array - Array of objects to process
 * @param value - Object with replacement values
 */
export const rplNullwith = (array, value) => {
    array.forEach((item) => {
        Object.keys(item).forEach((key) => {
            if (item[key] === null) {
                item[key] = value;
            }
        });
    });
};
/**
 * Generates unique random numbers within a range
 * @param count - Number of unique random numbers to generate
 * @param max - Maximum value (inclusive)
 * @returns Array of unique random numbers
 * @throws Error if count exceeds available range
 */
export const uniqueRandomNumbers = (count, max) => {
    if (count > max + 1) {
        throw new Error('Count exceeds the range of unique numbers available.');
    }
    const numbers = new Set();
    while (numbers.size < count) {
        numbers.add(Math.floor(Math.random() * (max + 1)));
    }
    return [...numbers];
};
