/**
 * Converts camelCase strings to kebab-case
 * @param str - The string to convert
 * @returns The kebab-cased string
 */
export const toKebabCase = (str) => {
    return str.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
};
/**
 * Checks if a string is valid JSON
 * @param value - The value to check
 * @returns True if the value is valid JSON
 */
export const isJSON = (value) => {
    const stringify = typeof value === 'string' ? value : JSON.stringify(value);
    const o = JSON.parse(stringify);
    return o && typeof o === 'object';
};
/**
 * Checks if a string is valid base64
 * @param str - The string to check
 * @returns True if the string is valid base64
 */
export const isBase64 = (str) => {
    if (str === '' || str.trim() === '') {
        return false;
    }
    try {
        return btoa(atob(str)) == str;
    }
    catch (err) {
        return false;
    }
};
