/**
 * Tag Input — shared models, types, and enums.
 */
export const TagInputSizeEnum = {
    SM: 'sm',
    MD: 'md',
    LG: 'lg',
};
export const TagInputVariantEnum = {
    DEFAULT: 'default',
    OUTLINED: 'outlined',
    FILLED: 'filled',
};
export const TagColorEnum = {
    PRIMARY: 'primary',
    SECONDARY: 'secondary',
    SUCCESS: 'success',
    WARNING: 'warning',
    DANGER: 'danger',
    INFO: 'info',
};
/** Convenience factory — fills in defaults so callers don't have to. */
export function createTag(label, color = TagColorEnum.PRIMARY, removable = true) {
    return {
        id: `tag-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        label,
        color,
        removable,
    };
}
