import { InjectionToken, PLATFORM_ID, inject } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
/**
 * Injection token for the Window object
 *
 * Similar to Angular's DOCUMENT token, this provides a safe way to access
 * the window object with SSR compatibility.
 *
 * @example
 * // Inject directly (recommended)
 * const window = inject(WINDOW);
 *
 * @example
 * // Constructor injection
 * constructor(@Inject(WINDOW) private window: Window | null) { }
 *
 * @example
 * // Check if window is available
 * const window = inject(WINDOW);
 * if (window) {
 *   window.localStorage.setItem('key', 'value');
 * }
 *
 * @example
 * // Usage in components
 * export class MyComponent {
 *   private window = inject(WINDOW);
 *
 *   openNewTab(url: string) {
 *     if (this.window) {
 *       this.window.open(url, '_blank');
 *     }
 *   }
 * }
 */
export const WINDOW = new InjectionToken('Window object token', {
    providedIn: 'root',
    factory: () => {
        const platformId = inject(PLATFORM_ID);
        // Return window only in browser environment
        return isPlatformBrowser(platformId) ? window : null;
    }
});
