/**
 * Carousel Helper Functions
 *
 * Pure utility functions for slide position calculations and responsive breakpoints.
 * No Angular DI or DOM manipulation — returns computed style values.
 */
import { CarouselDepthEnum } from './carousel.model';
// ============================================================================
// STACKED SLIDE CALCULATIONS
// ============================================================================
/**
 * Computes the shortest-distance diff between a slide and the active slide,
 * accounting for wrapping in loop mode.
 */
export function computeWrappedDiff(slideIndex, activeIndex, totalSlides, loop) {
    let diff = slideIndex - activeIndex;
    if (loop) {
        if (diff > totalSlides / 2) {
            diff -= totalSlides;
        }
        else if (diff < -totalSlides / 2) {
            diff += totalSlides;
        }
    }
    return diff;
}
/**
 * Computes the CSS styles for a stacked slide based on its position difference
 * from the active slide.
 */
export function computeStackedSlideStyles(params) {
    const { slideIndex, activeIndex, totalSlides, dragOffset, isDragging, loop } = params;
    const diff = computeWrappedDiff(slideIndex, activeIndex, totalSlides, loop);
    const transition = isDragging
        ? 'none'
        : 'transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1), opacity 0.4s ease, z-index 0.4s step-end';
    if (diff === 0) {
        // Active slide (on top)
        const rotate = dragOffset * 0.08;
        return {
            transform: `translate3d(${dragOffset}px, 0, 0) rotate(${rotate}deg) scale(1)`,
            opacity: '1',
            zIndex: CarouselDepthEnum.ActiveZIndex.toString(),
            pointerEvents: 'auto',
            transition,
        };
    }
    else if (diff > 0 && diff <= CarouselDepthEnum.MaxStackedVisible) {
        // Stacked slides behind
        const scale = 1 - diff * 0.05;
        const translateY = diff * -12;
        const translateZ = diff * -20;
        return {
            transform: `translate3d(0, ${translateY}px, ${translateZ}px) scale(${scale})`,
            opacity: (1 - diff * 0.25).toString(),
            zIndex: (CarouselDepthEnum.ActiveZIndex - diff).toString(),
            pointerEvents: 'none',
            transition,
        };
    }
    else if (diff < 0) {
        // Dismissed slides (swiped away)
        const rotate = -15 + (dragOffset < 0 ? dragOffset * 0.05 : 0);
        return {
            transform: `translate3d(calc(-150% + ${dragOffset}px), 0, 0) rotate(${rotate}deg) scale(0.9)`,
            opacity: '0',
            zIndex: CarouselDepthEnum.DismissedZIndex.toString(),
            pointerEvents: 'none',
            transition,
        };
    }
    else {
        // Hidden slides (beyond max visible stack)
        return {
            transform: 'translate3d(0, -36px, -60px) scale(0.85)',
            opacity: '0',
            zIndex: CarouselDepthEnum.HiddenZIndex.toString(),
            pointerEvents: 'none',
            transition,
        };
    }
}
// ============================================================================
// RESPONSIVE BREAKPOINTS
// ============================================================================
/**
 * Resolves the number of visible items based on current viewport width
 * and responsive breakpoint configuration.
 */
export function resolveResponsiveItems(viewportWidth, responsiveConfig, defaultItems) {
    if (responsiveConfig && Object.keys(responsiveConfig).length > 0) {
        const sortedBreaks = Object.keys(responsiveConfig)
            .map(Number)
            .sort((a, b) => b - a);
        const match = sortedBreaks.find((bp) => viewportWidth >= bp);
        if (match !== undefined) {
            return responsiveConfig[match].items;
        }
    }
    return defaultItems;
}
