/**
 * Promise utilities for timeout protection and async control
 */
/**
 * Applies timeout protection to a promise.
 * Rejects if the promise doesn't settle within the timeout duration.
 *
 * @example
 * // Timeout a long-running promise
 * const result = await withTimeout(somePromise, 5000);
 *
 * @example
 * // No timeout if timeoutMs is not provided or <= 0
 * const result = await withTimeout(somePromise); // Waits indefinitely
 */
export const withTimeout = async (promise, timeoutMs) => {
    if (!timeoutMs || timeoutMs <= 0) {
        return promise;
    }
    return Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error(`Operation timeout after ${timeoutMs}ms exceeded`)), timeoutMs)),
    ]);
};
