/**
 * Generic Search Scoring Utilities
 * Pure functions for calculating search relevance scores
 */
import { SearchMatchType, DEFAULT_SEARCH_WEIGHTS } from '../models/search.models';
import { containsQuery, exactMatch, extractPreview } from '@arun-bharath-ui/cmp-utils';
export { SearchMatchType, DEFAULT_SEARCH_WEIGHTS };
// ============================================================================
// Score Calculation Functions
// ============================================================================
/**
 * Calculate score for a field match
 */
export function scoreFieldMatch(fieldValue, query, matchType, weights = DEFAULT_SEARCH_WEIGHTS, caseSensitive = false) {
    if (!fieldValue || !query)
        return null;
    const isExact = exactMatch(fieldValue, query, caseSensitive);
    const isPartial = !isExact && containsQuery(fieldValue, query, caseSensitive);
    if (!isExact && !isPartial)
        return null;
    let score = 0;
    switch (matchType) {
        case SearchMatchType.Title:
            score = isExact ? weights.titleExact : weights.titlePartial;
            break;
        case SearchMatchType.Description:
            score = isExact ? weights.descriptionExact : weights.descriptionPartial;
            break;
        case SearchMatchType.Tag:
            score = isExact ? weights.tagExact : weights.tagPartial;
            break;
        case SearchMatchType.Content:
            score = weights.contentMatch;
            break;
        default:
            score = weights.contentMatch;
    }
    return {
        type: matchType,
        score,
        preview: extractPreview(fieldValue, query, 60, caseSensitive),
    };
}
/**
 * Calculate score for tag matches
 */
export function scoreTagMatches(tags, query, weights = DEFAULT_SEARCH_WEIGHTS, caseSensitive = false) {
    if (!tags || tags.length === 0)
        return [];
    const matches = [];
    for (const tag of tags) {
        const match = scoreFieldMatch(tag, query, SearchMatchType.Tag, weights, caseSensitive);
        if (match) {
            matches.push(match);
        }
    }
    return matches;
}
/**
 * Calculate total score from all matches
 */
export function calculateTotalScore(matches) {
    return matches.reduce((total, match) => total + match.score, 0);
}
/**
 * Sort search results by score (highest first)
 */
export function sortByScore(results) {
    return [...results].sort((a, b) => b.totalScore - a.totalScore);
}
/**
 * Filter results by minimum score
 */
export function filterByMinScore(results, minScore) {
    return results.filter((result) => result.totalScore >= minScore);
}
