import { HttpParams } from '@angular/common/http';
/**
 * URL validation regex pattern
 */
export const urlRegx = new RegExp(/[-a-zA-Z0-9@:%._+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_.+~#?&//=]*)/gi);
/**
 * Converts query parameters object to URL query string
 * @param qp - Query parameters object
 * @returns Formatted query string (e.g., "?userId=1&name=rowad")
 */
export const correctFormatForQueryUrl = (qp) => {
    if (qp === null || qp === undefined) {
        return '';
    }
    const qpAsStr = mapQueryParamsToUrl(qp);
    return qpAsStr.length === 0 ? '' : `?${qpAsStr.join('&')}`;
};
/**
 * Maps query parameters object to array of URL-formatted strings
 * @param qp - Query parameters object
 * @returns Array of formatted query parameters (e.g., ["userId=1", "name=rowad"])
 */
export const mapQueryParamsToUrl = (qp) => {
    return Object.keys(qp).map((key) => {
        return `${key}=${qp[key]}`;
    });
};
/**
 * Converts an object to HttpParams for HTTP requests
 * @param query - Query parameters object
 * @returns HttpParams instance
 */
export const getHttpParams = (query) => {
    const httpParams = new HttpParams();
    for (const key in query) {
        httpParams.append(key, `${query[key]}`);
    }
    return httpParams;
};
