import { HttpResponse } from '@angular/common/http';
import { of } from 'rxjs';
import { share, tap } from 'rxjs/operators';
import { CONTEXT_TOKEN } from '../http/http.constant';
// Cache stored globally for persistence across requests
const cache = new Map();
// Function to clear all cached responses
const clearAllCache = () => {
    cache.clear();
    console.log('Cache cleared!');
};
// Function to clear cache by request URL (or specific ID)
const clearCacheById = (id) => {
    cache.delete(id);
    console.log(`Cache for ${id} cleared!`);
};
export function cacheInterceptor(req, next) {
    // Clear cache based on context tokens if they are set
    const resetCacheById = req.context.get(CONTEXT_TOKEN.RESET_CACHE_BYID);
    const resetCache = req.context.get(CONTEXT_TOKEN.RESET_CACHE);
    if (resetCacheById) {
        clearCacheById(resetCacheById);
    }
    else if (resetCache) {
        clearAllCache();
    }
    if (req.context.get(CONTEXT_TOKEN.IS_CACHE_ENABLED)) {
        const cachedResponse = cache.get(req.urlWithParams);
        if (cachedResponse) {
            return of(cachedResponse.clone());
        }
        return next(req).pipe(tap((event) => {
            if (event instanceof HttpResponse) {
                cache.set(req.urlWithParams, event.clone());
                console.log(cache);
            }
            return event;
        }), share());
    }
    else {
        console.log('HANDLE REQ TO NEXT --->');
        return next(req);
    }
}
