/**
 * GUID generation types
 */
export var GUID_ENUM;
(function (GUID_ENUM) {
    GUID_ENUM["STRING"] = "STRING";
    GUID_ENUM["NUMBER"] = "NUMBER";
    GUID_ENUM["ALPHANUMERIC"] = "ALPHANUMERIC";
})(GUID_ENUM || (GUID_ENUM = {}));
/**
 * Generates a GUID/UUID in the specified format
 * @param type - The type of GUID to generate (default: NUMBER)
 * @param length - The length of the generated GUID (default: 36)
 * @returns Generated GUID string
 */
export const guidGenerator = (type = GUID_ENUM.NUMBER, length = 36) => {
    let baseId = '';
    const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    const S4 = () => (((1 + Math.random()) * 0x10000) | 0).toString(16).substring(1);
    switch (type) {
        case GUID_ENUM.STRING:
            for (let i = 0; i < length; i++) {
                baseId += letters.charAt(Math.floor(Math.random() * letters.length));
            }
            break;
        case GUID_ENUM.NUMBER:
            baseId = `${S4() + S4()}-${S4()}-${S4()}-${S4()}-${S4()}${S4()}${S4()}`;
            break;
        case GUID_ENUM.ALPHANUMERIC:
            for (let i = 0; i < length; i++) {
                baseId +=
                    letters.charAt(Math.floor(Math.random() * letters.length)) +
                        Math.floor(Math.random() * 10);
            }
            break;
        default:
            baseId = `${S4()}-${S4()}-${S4()}-${S4()}-${S4()}${S4()}${S4()}`;
            break;
    }
    return baseId.substring(0, length);
};
