/**
 * Stepper type enum for convenience
 */
export const StepperTypeEnum = {
    Horizontal: 'horizontal',
    Vertical: 'vertical',
};
/**
 * Step state enum for convenience
 */
export const StepStateEnum = {
    Pending: 'pending',
    Active: 'active',
    Completed: 'completed',
    Error: 'error',
};
/**
 * Stepper size enum for convenience
 */
export const StepperSizeEnum = {
    Small: 'sm',
    Medium: 'md',
    Large: 'lg',
};
/**
 * Factory function to create a step item with defaults
 */
export function createStepItem(label, options) {
    return {
        label,
        description: options?.description,
        icon: options?.icon,
        disabled: options?.disabled ?? false,
        state: options?.state ?? StepStateEnum.Pending,
        data: options?.data,
    };
}
/**
 * Default stepper configuration
 */
export const DEFAULT_STEPPER_CONFIG = {
    showNumbers: true,
    allowStepClick: true,
    showConnector: true,
    animated: true,
    showProgressBar: false,
    linear: true,
    labelPosition: 'bottom',
    showMobileNavigation: true,
};
