/**
 * Feature utility for consistent feature string/array normalization.
 * Single source of truth to avoid DRY violations.
 */
export class FeatureUtils {
    /**
     * Normalize feature to array format
     * @example
     * FeatureUtils.normalize('auth') // ['auth']
     * FeatureUtils.normalize(['auth', 'profile']) // ['auth', 'profile']
     */
    static normalize(feature) {
        return Array.isArray(feature) ? feature : [feature];
    }
    /**
     * Validate that features are properly formatted
     * @returns true if valid (non-empty, all strings)
     */
    static isValid(feature) {
        const features = this.normalize(feature);
        return features.length > 0 && features.every((f) => typeof f === 'string' && f.trim().length > 0);
    }
}
