/**
 * Field validation helpers for strict schema validation.
 * Provides reusable validation methods with clear error messages.
 */
export class ValidationUtility {
    static assertIsObject(val, label) {
        if (!val || typeof val !== 'object') {
            throw new Error(`${label} must be a valid JSON object.`);
        }
    }
    static requireString(val, fieldName) {
        if (typeof val !== 'string' || !val.trim()) {
            throw new Error(`Missing required string field: "${fieldName}".`);
        }
        return val;
    }
    static requireNumber(val, fieldName) {
        if (typeof val !== 'number' || isNaN(val)) {
            throw new Error(`Missing required numeric field: "${fieldName}".`);
        }
        return val;
    }
    static parseString(val) {
        return typeof val === 'string' && val.trim() ? val : undefined;
    }
    static requireEnum(val, enumValues, fieldName) {
        if (!enumValues.includes(val)) {
            throw new Error(`Invalid value for "${fieldName}": ${val}`);
        }
        return val;
    }
}
