import { InjectionToken } from '@angular/core';
/**
 * Injection token for providing date picker configuration
 *
 * This token allows configuration to be provided at the application level
 * (in app.config.ts) or at the component level (in component providers array).
 *
 * @example
 * // Global configuration in app.config.ts
 * providers: [
 *   {
 *     provide: DATE_PICKER_CONFIG_TOKEN,
 *     useValue: { locale: LocaleEnum.EnglishUS, firstDayOfWeek: FirstDayOfWeekEnum.Monday }
 *   }
 * ]
 *
 * @example
 * // Component-level configuration
 * @Component({
 *   selector: 'app-my-component',
 *   providers: [
 *     {
 *       provide: DATE_PICKER_CONFIG_TOKEN,
 *       useValue: { locale: LocaleEnum.French }
 *     }
 *   ]
 * })
 */
export const DATE_PICKER_CONFIG_TOKEN = new InjectionToken('DatePickerConfig');
