import { signal } from '@angular/core';
/**
 * Handle to the created modal, used to listen for results and control the modal.
 */
export class ModalRef {
    constructor(containerRef, appRef, onComplete, activeModal) {
        this.containerRef = containerRef;
        this.appRef = appRef;
        this.onComplete = onComplete;
        this.activeModal = activeModal;
        this._closed = signal(false);
        this.closed = this._closed.asReadonly();
        this._result = signal(undefined);
        this.resultSignal = this._result.asReadonly();
        this.result = new Promise((resolve) => {
            this._resolver = resolve;
        });
    }
    close(result) {
        this.finalize({ closed: true, dismissed: false, result });
    }
    dismiss(reason) {
        this.finalize({
            closed: false,
            dismissed: true,
            result: reason,
        });
    }
    finalize(outcome) {
        if (this._closed())
            return;
        this._closed.set(true);
        this._result.set(outcome);
        if (this.activeModal) {
            this.activeModal._finalize(outcome);
        }
        this._resolver(outcome);
        this.appRef.detachView(this.containerRef.hostView);
        this.containerRef.destroy();
        this.onComplete();
    }
}
