import { InjectionToken } from '@angular/core';
/**
 * Default dropdown configuration
 */
export const DEFAULT_DROPDOWN_CONFIG = {
    hasBackdrop: false,
    backdropClass: '',
    disposeOnClose: false, // Reuse overlay for better performance
};
/**
 * Injection token for dropdown configuration
 *
 * Usage:
 *
 * // In a component or module, provide custom config:
 * providers: [
 *   {
 *     provide: DROPDOWN_CONFIG,
 *     useValue: {
 *       scrollStrategyFactory: () => inject(Overlay).scrollStrategies.block(),
 *       hasBackdrop: true,
 *     }
 *   }
 * ]
 *
 * // Or use a factory:
 * providers: [
 *   {
 *     provide: DROPDOWN_CONFIG,
 *     useFactory: (overlay: Overlay) => ({
 *       scrollStrategyFactory: () => overlay.scrollStrategies.close(),
 *     }),
 *     deps: [Overlay]
 *   }
 * ]
 */
export const DROPDOWN_CONFIG = new InjectionToken('DROPDOWN_CONFIG', {
    providedIn: 'root',
    factory: () => DEFAULT_DROPDOWN_CONFIG,
});
